create type public.user_role as enum ('customer', 'admin');
create type public.order_status as enum ('new','confirmed','processing','packed','shipped','out_for_delivery','delivered','cancelled','returned','refunded');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, name text not null default '', role public.user_role not null default 'customer', created_at timestamptz not null default now());
create table public.brands (id bigint generated by default as identity primary key, name text not null unique, slug text not null unique, description text not null default '', created_at timestamptz not null default now());
create table public.categories (id bigint generated by default as identity primary key, name text not null unique, slug text not null unique, parent_id bigint references public.categories(id), description text not null default '', featured boolean not null default false);
create table public.products (id bigint generated by default as identity primary key, name text not null, brand_id bigint references public.brands(id), category_id bigint references public.categories(id), sku text not null unique, slug text not null unique, short_description text not null default '', description text not null default '', ingredients text not null default '', benefits text not null default '', usage text not null default '', warnings text not null default '', price integer, sale_price integer, stock_quantity integer not null default 0 check (stock_quantity >= 0), low_stock_threshold integer not null default 5, status text not null default 'draft', featured boolean not null default false, best_seller boolean not null default false, new_arrival boolean not null default true, image_url text, seo_title text not null default '', seo_description text not null default '', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.orders (id bigint generated by default as identity primary key, order_number text not null unique, user_id uuid references auth.users(id), customer_name text not null, phone text not null, email text not null default '', address text not null, city text not null, province text not null default '', postal_code text not null default '', notes text not null default '', subtotal integer not null, shipping integer not null default 0, discount integer not null default 0, total integer not null, status public.order_status not null default 'new', payment_method text not null default 'cod', created_at timestamptz not null default now());
create table public.order_items (id bigint generated by default as identity primary key, order_id bigint not null references public.orders(id) on delete cascade, product_id bigint not null references public.products(id), product_name text not null, quantity integer not null check (quantity > 0), unit_price integer not null);
alter table public.profiles enable row level security; alter table public.brands enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security;
create policy "public can read catalogue" on public.brands for select to anon, authenticated using (true); create policy "public can read categories" on public.categories for select to anon, authenticated using (true); create policy "public can read active products" on public.products for select to anon, authenticated using (status != 'archived');
create policy "customers read own profile" on public.profiles for select to authenticated using ((select auth.uid()) = id); create policy "customers read own orders" on public.orders for select to authenticated using ((select auth.uid()) = user_id); create policy "customers read own order items" on public.order_items for select to authenticated using (exists (select 1 from public.orders o where o.id = order_id and o.user_id = (select auth.uid())));
create policy "admins manage profiles" on public.profiles for all to authenticated using (exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.role = 'admin')) with check (exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.role = 'admin'));
create policy "admins manage products" on public.products for all to authenticated using (exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.role = 'admin')) with check (exists (select 1 from public.profiles p where p.id = (select auth.uid()) and p.role = 'admin'));
